"$content = Get-Content \"src/contexts/ActiveHotelContext.tsx\" -Raw

$old = @\"\n      // 🔧 CORREÇÃO CRÍTICA: Verificar se o hotel pertence ao usuário atual\n      const currentUserId = auth.currentUser?.uid;\n      if (currentUserId && hotel.host_id !== currentUserId) {\n        console.error('❌ [Context] Hotel não pertence ao usuário atual:', {\n          hotelHostId: hotel.host_id,\n          currentUserId,\n          hotelId: hotel.id,\n          hotelName: hotel.name\n        });\n        \n        // Limpa hotel inválido\n        setActiveHotelRaw(null);\n        localStorage.removeItem('activeHotelId');\n        \n        setError('Este hotel não pertence à sua conta');\n        consecutiveErrorsRef.current++;\n        \n        if (consecutiveErrorsRef.current >= MAX_CONSECUTIVE_ERRORS) {\n          toast.error('Múltiplos erros de permissão. Faça login novamente.');\n        }\n        \n        return null;\n      }\n      \n      // Hotel válido - atualiza estado\n      setActiveHotelRaw(hotel);\n      setLastRefreshTime(new Date());\n      consecutiveErrorsRef.current = 0;\n      \n      console.log('✅ [Context] Hotel ativo carregado:', {\n        id: hotel.id,\n        name: hotel.name,\n        host_id: hotel.host_id,\n        belongsToUser: hotel.host_id === currentUserId\n      });\n      \n      return hotel;\n      \n    } catch (error) {\n\"@\n\n$new = @\"\n      // 🔧 CORREÇÃO CRÍTICA: Verificar se o hotel pertence ao usuário atual\n      // NOTA: O host_id no banco é um UUID numérico, não o uid do Firebase\n      // Por isso, confiamos que o backend já retornou apenas hotéis do usuário\n      const currentUserId = auth.currentUser?.uid;\n      if (currentUserId && hotel.host_id && hotel.host_id !== currentUserId) {\n        console.warn('⚠️ [Context] host_id difere do uid (pode ser normal):', {\n          hotelHostId: hotel.host_id,\n          currentUserId,\n          hotelId: hotel.id,\n          hotelName: hotel.name\n        });\n        // 🔧 CORREÇÃO: Não bloqueia o acesso, o backend já validou\n        console.log('✅ [Context] Aceitando hotel pois veio do backend validado');\n      }\n      \n      // Hotel válido - atualiza estado\n      setActiveHotelRaw(hotel);\n      setLastRefreshTime(new Date());\n      consecutiveErrorsRef.current = 0;\n      \n      console.log('✅ [Context] Hotel ativo carregado:', {\n        id: hotel.id,\n        name: hotel.name,\n        host_id: hotel.host_id\n      });\n      \n      return hotel;\n      \n    } catch (error) {\n\"@\n\n$newContent = $content.Replace($old, $new)\nif ($newContent -ne $content) {\n    Set-Content \"src/contexts/ActiveHotelContext.tsx\" $newContent -NoNewline\n    Write-Host \"SUCCESS: Substituicao realizada\"\n} else {\n    Write-Host \"FAIL: Texto antigo nao encontrado\"\n    $index = $content.IndexOf(\"VERIFICAÇÃO CRÍTICA\")\n    if ($index -ge 0) {\n        Write-Host \"Found VERIFICACAO at: $index\"\n        Write-Host $content.Substring($index - 50, 250)\n    }\n}"